def graph_size(graph):
    return len(graph), sum(len(neighbors) for neighbors in graph.values())

print(graph_size({'A': ['B'], 'B': ['A'], 'C': []}))
print(graph_size({'A': ['A', 'A']}))
print(graph_size({}))

from collections import deque

def matrix_bfs_report(vertices, matrix, start):
    distance = {v: -1 for v in vertices}
    if not vertices:
        return distance, 0
    index = {v: i for i, v in enumerate(vertices)}
    distance[start] = 0
    queue = deque([start])
    checked = 0
    while queue:
        vertex = queue.popleft()
        for column, neighbor in enumerate(vertices):
            checked = checked + 1
            if matrix[index[vertex]][column] and distance[neighbor] == -1:
                distance[neighbor] = distance[vertex] + 1
                queue.append(neighbor)
    return distance, checked

print(matrix_bfs_report(['A', 'B', 'C'], [[False, True, False], [False, False, False], [False, False, False]], 'A'))
print(matrix_bfs_report(['A'], [[False]], 'A'))
print(matrix_bfs_report([], [], None))

from collections import deque

def bfs_distances(graph, start):
    distance = {v: -1 for v in graph}
    if not graph:
        return distance
    distance[start] = 0
    queue = deque([start])
    while queue:
        vertex = queue.popleft()
        for neighbor in graph[vertex]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[vertex] + 1
                queue.append(neighbor)
    return distance

def bfs_queries(graph, starts):
    return [bfs_distances(graph, start) for start in starts]

print(bfs_queries({'A': ['B'], 'B': [], 'C': []}, ['A', 'C']))
print(bfs_queries({'A': []}, ['A', 'A']))
print(bfs_queries({}, []))

